// ---- host logic: examples/api_tours/dom_tree/host.cpp ----
// API tour (C++ Wrapper): host-side DOM tree operations. Same page, checks and case as
// examples/c/ports/kui_api_dom_tree.c (and the Go / Rust ports): on start the host calls every
// lookup / traversal / tree-editing / HTML method once, checks the result and logs one row per
// check into #tour-log; #tour-result ends as "PASS n/n". The panel buttons repeat the calls on
// the visible sandboxes.
//
// Gaps (the Wrapper has no method for these exports; the public C handle is used instead):
//   kui_document_retain / kui_document_release  -> document.cHandle() + the C ABI
//   kui_element_retain / kui_element_release    -> element->cHandle() + the C ABI
// (Wrapper lifetimes are RAII: RefPtr<Document> / the document's element cache hold the C refs.)

#include <functional>
#include <sstream>
#include <vector>

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// known():  a documented behaviour the engine currently gets wrong (reported bug). A failure is
//           logged as "KNOWN BUG" and kept out of the verdict; once it passes it counts as ok.

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    (out << ... << parts);
    return out.str();
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    if (g_known) text += cat(" (known bugs: ", g_known, ")");
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// ---- Small readers ---------------------------------------------------------------------------

std::string id_of(const kui::Element* element) { return element ? element->id() : std::string(); }
std::string tag_of(const kui::Element* element) { return element ? element->tagName() : std::string(); }
std::string text_of(const kui::Element* element) {
    return element ? element->textContent() : std::string();
}
bool has_id(const kui::Element* element, const char* id) { return element && element->id() == id; }
unsigned children_of(const kui::Element* element) {
    return element ? element->childElementCount() : 0u;
}

std::string join_texts(const std::vector<kui::RefPtr<kui::Element>>& items) {
    std::string out;
    for (const auto& item : items) out += (out.empty() ? "" : ",") + item->textContent();
    return out;
}

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = g_doc->getElementById(id)) element->setTextContent(text);
}

// ---- Document lookups: root / head / body, id, selectors, class and tag lists, hit test ----

void check_lookups() {
    kui::Element* root = g_doc->documentElement();
    check("doc.root", tag_of(root) == "html", cat("root tag '", tag_of(root), "'"));

    kui::Element* head = g_doc->head();
    const std::string title = text_of(head ? head->querySelector("title") : nullptr);
    check("doc.head", tag_of(head) == "head" && title == "KUI API \xe2\x80\x94 DOM tree",
          cat("head tag '", tag_of(head), "', <title> '", title, "'"));

    kui::Element* body = g_doc->body();
    kui::Element* parent = body ? body->parentElement() : nullptr;
    check("doc.body", body && tag_of(parent) == "html", cat("body parent tag '", tag_of(parent), "'"));

    kui::Element* found = g_doc->getElementById("lookup-box");
    check("doc.get_element_by_id", id_of(found) == "lookup-box", cat("id '", id_of(found), "'"));
    found = g_doc->getElementById("no-such-id");
    check("doc.get_element_by_id-missing", found == nullptr, "a missing id returned an element");

    found = g_doc->querySelector("#lookup-box .hot");
    check("doc.query_selector", text_of(found) == "beta", cat("first .hot text '", text_of(found), "'"));

    auto items = g_doc->querySelectorAll(".chip");
    check("doc.query_selector_all", items.size() == 4 && join_texts(items) == "alpha,beta,gamma,delta",
          cat("count ", items.size(), " texts '", join_texts(items), "'"));

    items = g_doc->getElementsByClassName("hot");
    check("doc.get_elements_by_class_name", items.size() == 2 && join_texts(items) == "beta,delta",
          cat("count ", items.size(), " texts '", join_texts(items), "'"));
    // kui_c.h: several space-separated classes must all match.
    items = g_doc->getElementsByClassName("chip hot");
    known("doc.get_elements_by_class_name-multi", items.size() == 2 && join_texts(items) == "beta,delta",
          "a multi-class query matches nothing",
          cat("count ", items.size(), " texts '", join_texts(items), "'"));

    items = g_doc->getElementsByTagName("em");
    check("doc.get_elements_by_tag_name", items.size() == 1 && join_texts(items) == "delta",
          cat("count ", items.size(), " texts '", join_texts(items), "'"));

    found = g_doc->getElementById("lookup-box");
    kui::Element* em = found ? found->querySelector("em") : nullptr;
    check("el.query_selector", text_of(em) == "delta", cat("em text '", text_of(em), "'"));
    items = found ? found->querySelectorAll("span") : std::vector<kui::RefPtr<kui::Element>>{};
    check("el.query_selector_all", items.size() == 3 && join_texts(items) == "alpha,beta,gamma",
          cat("count ", items.size(), " texts '", join_texts(items), "'"));

    // Hit test the centre of #hit-target in viewport coordinates.
    kui::Element* target = g_doc->getElementById("hit-target");
    const kui::Rect rect = target ? target->boundingClientRect() : kui::Rect{};
    kui::Element* hit = g_doc->elementFromPoint(rect.x + rect.width / 2, rect.y + rect.height / 2);
    check("doc.element_from_point", has_id(hit, "hit-target"),
          cat("rect ", rect.x, ",", rect.y, " ", rect.width, "x", rect.height, " hit '", id_of(hit), "'"));

    // An extra document reference is balanced by a release; the document stays usable.
    // Gap: no Wrapper method for kui_document_retain / kui_document_release.
    KuiStatus status = kui_document_retain(g_doc->cHandle());
    if (status == KUI_OK) status = kui_document_release(g_doc->cHandle());
    found = g_doc->getElementById("lookup-box");
    check("doc.retain", status == KUI_OK && found, cat("status ", static_cast<int>(status)));
}

// ---- Traversal: parent, siblings, first / last child, closest and matches ---------------

void check_traversal() {
    kui::Element* t2 = g_doc->getElementById("t2");
    kui::Element* t4 = g_doc->getElementById("t4");
    kui::Element* list = g_doc->getElementById("trav-list");
    if (!t2 || !t4 || !list) {
        check("el.traversal-fixture", false, "#t2 / #t4 / #trav-list missing");
        return;
    }

    kui::Element* got = t2->parentElement();
    check("el.parent", has_id(got, "trav-list"), cat("parent '", id_of(got), "'"));
    got = t2->nextElementSibling();
    check("el.next_sibling", has_id(got, "t3"), cat("next '", id_of(got), "'"));
    got = t2->previousElementSibling();
    check("el.previous_sibling", has_id(got, "t1"), cat("previous '", id_of(got), "'"));
    got = t4->nextElementSibling();
    check("el.next_sibling-end", got == nullptr, cat("next of the last item '", id_of(got), "'"));

    kui::Element* first = list->firstElementChild();
    kui::Element* last = list->lastElementChild();
    check("el.first_last_child", has_id(first, "t1") && has_id(last, "t4") && children_of(list) == 4,
          cat("first '", id_of(first), "' last '", id_of(last), "' count ", children_of(list)));

    got = t2->closest("ul");
    check("el.closest-ancestor", has_id(got, "trav-list"), cat("closest(ul) '", id_of(got), "'"));
    got = t2->closest("li");
    check("el.closest-inclusive", has_id(got, "t2"), cat("closest(li) '", id_of(got), "'"));
    got = t2->closest("table");
    check("el.closest-none", got == nullptr, cat("closest(table) '", id_of(got), "'"));

    const bool mid = t2->matches("li.mid");
    check("el.matches", mid, "matches(li.mid) = false");
    const bool other = t2->matches("#t1");
    check("el.matches-false", !other, "matches(#t1) = true");
}

// ---- Create & insert (in the hidden #scratch): create, append, insert_before, clone, replace --

void check_create_insert() {
    kui::Element* scratch = g_doc->getElementById("scratch");
    if (!scratch) {
        check("el.scratch-fixture", false, "#scratch missing");
        return;
    }
    auto a = g_doc->createElement("div");
    a->setAttribute("id", "sc-a");
    a->setAttribute("data-k", "v");
    scratch->appendChild(a);
    kui::Element* got = g_doc->getElementById("sc-a");
    const std::string data = got ? got->getAttribute("data-k") : std::string();
    check("el.create_append", children_of(scratch) == 1 && got && data == "v",
          cat("children ", children_of(scratch), ", found ", got != nullptr, ", data-k '", data, "'"));

    auto first = g_doc->createElement("p");
    first->setAttribute("id", "sc-first");
    kui::Element* inserted = scratch->insertBefore(first, a.get());
    got = scratch->firstElementChild();
    check("el.insert_before", inserted == first.get() && has_id(got, "sc-first"),
          cat("first child '", id_of(got), "'"));

    auto src = g_doc->createElement("div");
    src->setAttribute("id", "sc-src");
    src->setInnerHTML("<b>bold</b> tail");
    scratch->appendChild(src);
    auto deep = src->cloneNode(true);
    auto shallow = src->cloneNode(false);

    kui::Element* bold = deep ? deep->querySelector("b") : nullptr;
    kui::Element* deep_parent = deep ? deep->parentElement() : nullptr;
    check("el.clone-deep", text_of(deep.get()) == "bold tail" && !deep_parent && bold,
          cat("text '", text_of(deep.get()), "', parent ", deep_parent != nullptr, ", <b> ", bold != nullptr));
    check("el.clone-shallow", shallow && text_of(shallow.get()).empty() && children_of(shallow.get()) == 0 &&
          tag_of(shallow.get()) == "div",
          cat("text '", text_of(shallow.get()), "', children ", children_of(shallow.get()), ", tag '",
              tag_of(shallow.get()), "'"));

    // The deep copy (renamed, ids stay unique) takes #sc-a's place.
    kui::Element* replaced = nullptr;
    if (deep) {
        deep->setAttribute("id", "sc-copy");
        replaced = scratch->replaceChild(deep, a.get());
    }
    kui::Element* old_parent = a->parentElement();
    kui::Element* new_parent = deep ? deep->parentElement() : nullptr;
    kui::Element* lookup = g_doc->getElementById("sc-a");
    check("el.replace_child", replaced && replaced == deep.get() && !old_parent && !lookup &&
          has_id(new_parent, "scratch"),
          cat("replaced ", replaced != nullptr, ", old parent ", old_parent != nullptr, ", lookup ",
              lookup != nullptr));
}

// ---- Remove, attributes and handle references (still in #scratch) ----------------------

void check_remove_attributes() {
    kui::Element* scratch = g_doc->getElementById("scratch");
    kui::Element* first = g_doc->getElementById("sc-first");
    kui::Element* src = g_doc->getElementById("sc-src");
    kui::Element* copy = g_doc->getElementById("sc-copy");
    if (!scratch || !first || !src || !copy) {
        check("el.remove-fixture", false, "#scratch / #sc-first / #sc-src / #sc-copy missing");
        return;
    }

    // A removed element leaves the document, but our handle keeps it alive and readable.
    first->remove();
    kui::Element* got = g_doc->getElementById("sc-first");
    check("el.remove", !got && tag_of(first) == "p",
          cat("still found ", got != nullptr, ", handle tag '", tag_of(first), "'"));

    const unsigned before = children_of(scratch);
    auto removed = scratch->removeChild(src);
    got = src->parentElement();
    check("el.remove_child", removed.get() == src && children_of(scratch) + 1 == before && !got,
          cat("children ", before, " -> ", children_of(scratch), ", parent ", got != nullptr));

    copy->setAttribute("title", "hello");
    check("el.set_get_attribute", copy->getAttribute("title") == "hello",
          cat("title '", copy->getAttribute("title"), "'"));
    check("el.has_attribute", copy->hasAttribute("title"), "hasAttribute(title) = false");
    copy->removeAttribute("title");
    // The Wrapper reads a missing attribute (KUI_ERR_NOT_FOUND) as an empty string.
    check("el.remove_attribute", !copy->hasAttribute("title") && copy->getAttribute("title").empty(),
          cat("has ", copy->hasAttribute("title"), ", value '", copy->getAttribute("title"), "'"));

    // retain adds a reference; after one release the handle is still ours.
    // Gap: no Wrapper method for kui_element_retain / kui_element_release.
    const KuiStatus status = kui_element_retain(copy->cHandle());
    if (status == KUI_OK) kui_element_release(copy->cHandle());
    check("el.retain", status == KUI_OK && copy->id() == "sc-copy",
          cat("status ", static_cast<int>(status), ", id '", copy->id(), "'"));
}

// ---- HTML & text: inner / outer HTML, insert_adjacent_html, text nodes ------------------

// ---- Form control state: the current value / checked / selected index, not the content attribute ----

void check_form_state() {
    kui::Element* scratch = g_doc->getElementById("scratch");
    if (!scratch) return;
    auto box = g_doc->createElement("div");
    scratch->appendChild(box);
    box->setInnerHTML("<input id=\"sc-fv\" type=\"text\" value=\"initial\"><select id=\"sc-fs\"><option value=\"s\">S</option><option value=\"m\" selected>M</option><option value=\"l\">L</option></select><input id=\"sc-fc\" type=\"checkbox\"><i id=\"sc-fi\">x</i>");
    kui::Element* input = g_doc->getElementById("sc-fv");
    kui::Element* select = g_doc->getElementById("sc-fs");
    kui::Element* checkbox = g_doc->getElementById("sc-fc");
    kui::Element* plain = g_doc->getElementById("sc-fi");
    if (!input || !select || !checkbox || !plain) {
        check("form.setup", false, "form fixture missing");
        return;
    }

    const std::string initial = input->value();
    input->setValue("Ada");
    check("el.set_get_value", initial == "initial" && input->value() == "Ada" &&
          input->getAttribute("value") == "initial",
          cat("initial '", initial, "', current '", input->value(), "', attribute '", input->getAttribute("value"), "'"));

    const int before = select->selectedIndex();
    select->setSelectedIndex(2);
    check("el.set_get_selected_index", before == 1 && select->selectedIndex() == 2 && select->value() == "l",
          cat("before ", before, ", after ", select->selectedIndex(), ", value '", select->value(), "'"));

    const bool unchecked = !checkbox->checked();
    checkbox->setChecked(true);
    check("el.set_get_checked", unchecked && checkbox->checked(), cat("unchecked first ", unchecked, ", now ", checkbox->checked()));

    // An element with no form state: value() falls back to the attribute, selectedIndex() is not supported.
    bool unsupported = false;
    try {
        (void)plain->selectedIndex();
    } catch (const kui::Error&) {
        unsupported = true;
    }
    check("el.form-not-supported", unsupported && plain->value().empty(), cat("unsupported ", unsupported));
}

void check_html_text() {
    kui::Element* scratch = g_doc->getElementById("scratch");
    if (!scratch) return;
    auto box = g_doc->createElement("div");
    scratch->appendChild(box);

    box->setInnerHTML("<i>a</i><i>b</i>");
    check("el.set_inner_html", children_of(box.get()) == 2, cat("children ", children_of(box.get())));
    check("el.get_inner_html", box->innerHTML() == "<i>a</i><i>b</i>", cat("innerHTML '", box->innerHTML(), "'"));

    box->setInnerHTML("<p id=\"sc-o\" class=\"x\">hi</p>");
    kui::Element* inner = g_doc->getElementById("sc-o");
    const std::string outer = inner ? inner->outerHTML() : std::string();
    const bool tail = outer.size() >= 6 && outer.compare(outer.size() - 6, 6, "hi</p>") == 0;
    check("el.get_outer_html", outer.rfind("<p", 0) == 0 && outer.find("id=\"sc-o\"") != std::string::npos &&
          outer.find("class=\"x\"") != std::string::npos && tail, cat("outerHTML '", outer, "'"));

    box->setInnerHTML("<span id=\"sc-t\">T</span>");
    inner = g_doc->getElementById("sc-t");
    if (inner) {
        inner->insertAdjacentHTML("beforebegin", "<i>1</i>");
        inner->insertAdjacentHTML("afterbegin", "<i>2</i>");
        inner->insertAdjacentHTML("beforeend", "<i>3</i>");
        inner->insertAdjacentHTML("afterend", "<i>4</i>");
    }
    check("el.insert_adjacent_html", box->textContent() == "12T34" && text_of(inner) == "2T3" &&
          children_of(box.get()) == 3,
          cat("box text '", box->textContent(), "', target text '", text_of(inner), "', box children ",
              children_of(box.get())));

    auto span = g_doc->createElement("span");
    span->setTextContent("a");
    span->appendText("b");
    check("el.append_text", span->textContent() == "ab" && span->innerHTML() == "ab" &&
          children_of(span.get()) == 0,
          cat("text '", span->textContent(), "', innerHTML '", span->innerHTML(), "'"));

    // setTextContent never parses markup: it becomes one escaped text node.
    span->setTextContent("<b>x</b>");
    check("el.set_text_content", span->textContent() == "<b>x</b>" && children_of(span.get()) == 0,
          cat("text '", span->textContent(), "', children ", children_of(span.get())));
    // HTML serialization escapes '<' '>' '&' in text, so innerHTML parses back to the same text.
    check("el.get_inner_html-escapes-text", span->innerHTML() == "&lt;b&gt;x&lt;/b&gt;",
          cat("innerHTML '", span->innerHTML(), "'"));
}

// ---- Panel buttons -----------------------------------------------------------------------

int g_build_serial = 0;

void on_lookup_count() {
    const auto chips = g_doc->querySelectorAll(".chip").size();
    const auto hot = g_doc->getElementsByClassName("hot").size();
    const auto em = g_doc->getElementsByTagName("em").size();
    set_text("lookup-out", cat("chips=", chips, " | hot=", hot, " | em=", em));
}

void on_lookup_hit() {
    kui::Element* target = g_doc->getElementById("hit-target");
    const kui::Rect rect = target ? target->boundingClientRect() : kui::Rect{};
    kui::Element* hit = g_doc->elementFromPoint(rect.x + rect.width / 2, rect.y + rect.height / 2);
    set_text("lookup-out", cat("element_from_point -> #", hit ? id_of(hit) : std::string("(none)")));
}

void on_lookup_root() {
    set_text("lookup-out", cat("root=", tag_of(g_doc->documentElement()), " | head=", tag_of(g_doc->head()),
                               " | body=", tag_of(g_doc->body())));
}

// Moves the "cur" highlight to the next / previous item, wrapping at the ends.
void move_highlight(bool forward) {
    kui::Element* current = g_doc->querySelector("#trav-list li.cur");
    kui::Element* list = g_doc->getElementById("trav-list");
    if (!current || !list) return;
    kui::Element* target = forward ? current->nextElementSibling() : current->previousElementSibling();
    if (!target) target = forward ? list->firstElementChild() : list->lastElementChild();
    current->removeClass("cur");
    if (target) target->addClass("cur");
    set_text("trav-out", "#" + id_of(target));
}

void on_trav_info() {
    kui::Element* current = g_doc->querySelector("#trav-list li.cur");
    kui::Element* parent = current ? current->parentElement() : nullptr;
    kui::Element* panel = current ? current->closest("section.panel") : nullptr;
    const bool mid = current && current->matches(".mid");
    set_text("trav-out", cat("parent=#", id_of(parent), " | closest(.panel)=#", id_of(panel),
                             " | matches(.mid)=", mid ? "yes" : "no"));
}

void show_build_count(const kui::Element* box) { set_text("build-out", cat("children=", children_of(box))); }

void on_build_append() {
    kui::Element* box = g_doc->getElementById("build-box");
    if (box) {
        auto item = g_doc->createElement("p");
        item->setClassName("item");
        item->setTextContent(cat("item ", ++g_build_serial));
        box->appendChild(item);
    }
    show_build_count(box);
}

void on_build_prepend() {
    kui::Element* box = g_doc->getElementById("build-box");
    if (box) {
        auto item = g_doc->createElement("p");
        item->setClassName("item");
        item->setTextContent(cat("first ", ++g_build_serial));
        box->insertBefore(item, box->firstElementChild());  // nullptr appends
    }
    show_build_count(box);
}

void on_build_clone() {
    kui::Element* box = g_doc->getElementById("build-box");
    kui::Element* seed = g_doc->getElementById("build-seed");
    if (box && seed) {
        if (auto copy = seed->cloneNode(true)) {
            copy->setAttribute("id", cat("seed-copy-", ++g_build_serial));
            box->appendChild(copy);
        }
    }
    show_build_count(box);
}

void on_build_replace() {
    kui::Element* box = g_doc->getElementById("build-box");
    kui::Element* first = box ? box->firstElementChild() : nullptr;
    if (first) {
        auto item = g_doc->createElement("p");
        item->setClassName("replaced");
        item->setTextContent(cat("replaced ", ++g_build_serial));
        box->replaceChild(item, first);
    }
    show_build_count(box);
}

void show_rm_state() {
    kui::Element* box = g_doc->getElementById("rm-box");
    const bool flagged = box && box->hasAttribute("data-flag");
    set_text("rm-out", cat("left=", children_of(box), " | data-flag=", flagged ? "on" : "removed"));
}

void on_rm_last() {
    kui::Element* box = g_doc->getElementById("rm-box");
    if (kui::Element* last = box ? box->lastElementChild() : nullptr) last->remove();
    show_rm_state();
}

void on_rm_first() {
    kui::Element* box = g_doc->getElementById("rm-box");
    if (kui::Element* first = box ? box->firstElementChild() : nullptr) box->removeChild(first);
    show_rm_state();
}

void on_rm_attr() {
    if (kui::Element* box = g_doc->getElementById("rm-box")) {
        if (box->hasAttribute("data-flag")) box->removeAttribute("data-flag");
        else box->setAttribute("data-flag", "on");
    }
    show_rm_state();
}

void on_rm_retain() {
    kui::Element* box = g_doc->getElementById("rm-box");
    // Gap: no Wrapper method for kui_element_retain / kui_element_release.
    if (box && kui_element_retain(box->cHandle()) == KUI_OK) kui_element_release(box->cHandle());
    set_text("rm-out", "retained handle -> #" + id_of(box));
}

void on_html_reset() {
    kui::Element* box = g_doc->getElementById("html-box");
    if (box) box->setInnerHTML("<span id=\"html-core\">core</span>");
    set_text("html-out", box ? box->innerHTML() : std::string());
}

void on_html_adjacent() {
    if (kui::Element* core = g_doc->getElementById("html-core")) {
        core->insertAdjacentHTML("beforebegin", "<i>[</i>");
        core->insertAdjacentHTML("afterbegin", "<i>(</i>");
        core->insertAdjacentHTML("beforeend", "<i>)</i>");
        core->insertAdjacentHTML("afterend", "<i>]</i>");
    }
    set_text("html-out", text_of(g_doc->getElementById("html-box")));
}

void on_html_text() {
    kui::Element* core = g_doc->getElementById("html-core");
    if (core) core->appendText("+");
    set_text("html-out", text_of(core));
}

void on_html_outer() {
    kui::Element* core = g_doc->getElementById("html-core");
    set_text("html-out", core ? core->outerHTML() : std::string());
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = g_doc->getElementById(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) { handler(); });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;

    run_group("lookups", check_lookups);
    run_group("traversal", check_traversal);
    run_group("create", check_create_insert);
    run_group("remove", check_remove_attributes);
    run_group("html", check_html_text);
    run_group("form", check_form_state);
    finish();

    on_click("btn-lookup-count", on_lookup_count);
    on_click("btn-lookup-hit", on_lookup_hit);
    on_click("btn-lookup-root", on_lookup_root);
    on_click("btn-trav-prev", [] { move_highlight(false); });
    on_click("btn-trav-next", [] { move_highlight(true); });
    on_click("btn-trav-info", on_trav_info);
    on_click("btn-build-append", on_build_append);
    on_click("btn-build-prepend", on_build_prepend);
    on_click("btn-build-clone", on_build_clone);
    on_click("btn-build-replace", on_build_replace);
    on_click("btn-rm-last", on_rm_last);
    on_click("btn-rm-first", on_rm_first);
    on_click("btn-rm-attr", on_rm_attr);
    on_click("btn-rm-retain", on_rm_retain);
    on_click("btn-html-reset", on_html_reset);
    on_click("btn-html-adjacent", on_html_adjacent);
    on_click("btn-html-text", on_html_text);
    on_click("btn-html-outer", on_html_outer);
}
// ---- end of examples/api_tours/dom_tree/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 DOM tree";
        config.width = 1100;
        config.height = 760;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_dom_tree] %s\n", error.what());
        return 9;
    }
}
